{
  "name": "FleetInspection",
  "type": "object",
  "description": "Completed or in-progress Fleet equipment inspection/checklist record with evidence and guarded Fleet work-order follow-up.",
  "properties": {
    "equipment_id": {
      "type": "string"
    },
    "template_id": {
      "type": "string"
    },
    "template_name": {
      "type": "string"
    },
    "inspection_type": {
      "type": "string",
      "enum": [
        "pre_trip",
        "post_trip",
        "daily",
        "weekly",
        "monthly",
        "safety",
        "custom"
      ]
    },
    "inspector_email": {
      "type": "string"
    },
    "inspector_name": {
      "type": "string"
    },
    "status": {
      "type": "string",
      "enum": [
        "draft",
        "passed",
        "failed",
        "needs_attention"
      ],
      "default": "draft"
    },
    "started_at": {
      "type": "string",
      "format": "date-time"
    },
    "completed_at": {
      "type": "string",
      "format": "date-time"
    },
    "meter_value": {
      "type": "number",
      "minimum": 0
    },
    "meter_unit": {
      "type": "string",
      "enum": [
        "miles",
        "hours"
      ]
    },
    "responses": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "item_key": {
            "type": "string"
          },
          "label": {
            "type": "string"
          },
          "result": {
            "type": "string"
          },
          "value": {
            "type": "string"
          },
          "notes": {
            "type": "string"
          },
          "photo_urls": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "severity": {
            "type": "string",
            "enum": [
              "low",
              "medium",
              "high",
              "critical"
            ]
          },
          "fail_creates_work_order": {
            "type": "boolean"
          }
        }
      }
    },
    "failed_item_count": {
      "type": "number",
      "minimum": 0
    },
    "notes": {
      "type": "string"
    },
    "photo_urls": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "generated_work_order_ids": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "creation_key": {
      "type": "string"
    }
  },
  "required": [
    "equipment_id",
    "template_id",
    "template_name",
    "inspection_type",
    "status",
    "started_at",
    "creation_key"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    }
  }
}

{
  "name": "FleetInspectionTemplate",
  "type": "object",
  "description": "Reusable CCS Fleet inspection/checklist template. Fleet-only and separate from signage workflows.",
  "properties": {
    "name": {
      "type": "string"
    },
    "description": {
      "type": "string"
    },
    "inspection_type": {
      "type": "string",
      "enum": [
        "pre_trip",
        "post_trip",
        "daily",
        "weekly",
        "monthly",
        "safety",
        "custom"
      ]
    },
    "applicable_equipment_types": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "items": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "key": {
            "type": "string"
          },
          "label": {
            "type": "string"
          },
          "instructions": {
            "type": "string"
          },
          "response_type": {
            "type": "string",
            "enum": [
              "pass_fail",
              "checkbox",
              "text",
              "number"
            ]
          },
          "required": {
            "type": "boolean"
          },
          "severity": {
            "type": "string",
            "enum": [
              "low",
              "medium",
              "high",
              "critical"
            ]
          },
          "fail_creates_work_order": {
            "type": "boolean"
          }
        }
      }
    },
    "active": {
      "type": "boolean",
      "default": true
    },
    "created_by_email": {
      "type": "string"
    },
    "creation_key": {
      "type": "string"
    }
  },
  "required": [
    "name",
    "inspection_type",
    "items",
    "active",
    "creation_key"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    }
  }
}

{
  "name": "FleetLifecycleProfile",
  "type": "object",
  "description": "Fleet asset lifecycle and replacement planning profile. Fleet-only financial/strategic data.",
  "properties": {
    "equipment_id": {
      "type": "string"
    },
    "acquisition_cost": {
      "type": "number",
      "minimum": 0
    },
    "acquisition_date": {
      "type": "string",
      "format": "date"
    },
    "current_value": {
      "type": "number",
      "minimum": 0
    },
    "target_replacement_date": {
      "type": "string",
      "format": "date"
    },
    "target_mileage_hours": {
      "type": "number",
      "minimum": 0
    },
    "expected_residual_value": {
      "type": "number",
      "minimum": 0
    },
    "replacement_status": {
      "type": "string",
      "enum": [
        "monitor",
        "plan",
        "replace_soon",
        "approved",
        "replaced"
      ],
      "default": "monitor"
    },
    "annual_budget": {
      "type": "number",
      "minimum": 0
    },
    "notes": {
      "type": "string"
    },
    "updated_by_email": {
      "type": "string"
    },
    "creation_key": {
      "type": "string"
    }
  },
  "required": [
    "equipment_id"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    }
  }
}

{
  "name": "FleetMaintenanceMeterRule",
  "type": "object",
  "description": "Fleet maintenance trigger rule based on odometer mileage or engine/equipment hours. Supplements FleetMaintenanceTask without replacing date recurrence.",
  "properties": {
    "equipment_id": {
      "type": "string"
    },
    "maintenance_task_id": {
      "type": "string"
    },
    "meter_type": {
      "type": "string",
      "enum": [
        "odometer_miles",
        "engine_hours",
        "manual"
      ]
    },
    "interval_value": {
      "type": "number",
      "minimum": 0
    },
    "next_due_value": {
      "type": "number",
      "minimum": 0
    },
    "last_service_value": {
      "type": "number",
      "minimum": 0
    },
    "lead_value": {
      "type": "number",
      "minimum": 0,
      "default": 0
    },
    "trigger_mode": {
      "type": "string",
      "enum": [
        "meter_only",
        "date_or_meter"
      ],
      "default": "date_or_meter"
    },
    "source": {
      "type": "string",
      "enum": [
        "bouncie",
        "manual"
      ],
      "default": "manual"
    },
    "enabled": {
      "type": "boolean",
      "default": true
    },
    "notes": {
      "type": "string"
    },
    "creation_key": {
      "type": "string"
    }
  },
  "required": [
    "equipment_id",
    "maintenance_task_id",
    "meter_type",
    "interval_value"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    }
  }
}

{
  "name": "FleetMaintenanceTask",
  "type": "object",
  "description": "Fleet maintenance schedule/task. Completely separate from the Sign Maintenance estimator.",
  "properties": {
    "title": {
      "type": "string"
    },
    "description": {
      "type": "string"
    },
    "equipment_id": {
      "type": "string",
      "description": "Linked FleetEquipment id."
    },
    "type": {
      "type": "string",
      "enum": [
        "recurring",
        "one_off"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high",
        "critical"
      ],
      "default": "medium"
    },
    "frequency": {
      "type": "string",
      "enum": [
        "daily",
        "weekly",
        "bi_weekly",
        "monthly",
        "bi_monthly",
        "quarterly",
        "every_6_months",
        "annually",
        "custom"
      ]
    },
    "custom_frequency_value": {
      "type": "number"
    },
    "custom_frequency_unit": {
      "type": "string",
      "enum": [
        "days",
        "weeks",
        "months",
        "years"
      ]
    },
    "estimated_duration": {
      "type": "number"
    },
    "start_date": {
      "type": "string",
      "format": "date"
    },
    "assigned_to": {
      "type": "string"
    },
    "status": {
      "type": "string",
      "enum": [
        "pending",
        "in_progress",
        "completed",
        "overdue"
      ],
      "default": "pending"
    },
    "parts_needed": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "part_name": {
            "type": "string"
          },
          "quantity": {
            "type": "number"
          },
          "notes": {
            "type": "string"
          }
        }
      }
    },
    "fluids_needed": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "fluid_type": {
            "type": "string"
          },
          "quantity": {
            "type": "number"
          },
          "unit": {
            "type": "string",
            "enum": [
              "quarts",
              "gallons",
              "pints",
              "ounces"
            ],
            "default": "quarts"
          },
          "notes": {
            "type": "string"
          }
        }
      }
    },
    "generation_key": {
      "type": "string",
      "description": "Deterministic key/receipt for retry-safe scheduled work-order generation."
    },
    "last_generated_for_date": {
      "type": "string",
      "format": "date"
    },
    "creation_key": {
      "type": "string",
      "description": "Stable client-generated idempotency key for a logical Fleet maintenance schedule create operation."
    },
    "migration_source_app_id": {
      "type": "string"
    },
    "migration_source_entity": {
      "type": "string"
    },
    "migration_source_id": {
      "type": "string"
    },
    "migration_source_created_date": {
      "type": "string"
    },
    "migration_source_updated_date": {
      "type": "string"
    },
    "migration_batch": {
      "type": "string"
    }
  },
  "required": [
    "title",
    "equipment_id",
    "type"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    }
  }
}

{
  "name": "FleetMaintenanceWorkOrder",
  "type": "object",
  "description": "Fleet maintenance work order. Completely separate from customer/signage WorkOrder and never enters the signage production pipeline.",
  "properties": {
    "work_order_number": {
      "type": "string"
    },
    "equipment_id": {
      "type": "string",
      "description": "Linked FleetEquipment id when resolvable. Optional so historical orphan work orders can be preserved."
    },
    "source_equipment_id": {
      "type": "string",
      "description": "Original FleetMaster Equipment id, retained even if the relationship cannot be resolved."
    },
    "maintenance_task_id": {
      "type": "string",
      "description": "Linked FleetMaintenanceTask id when resolvable."
    },
    "source_maintenance_task_id": {
      "type": "string",
      "description": "Original FleetMaster MaintenanceTask id."
    },
    "title": {
      "type": "string"
    },
    "description": {
      "type": "string"
    },
    "type": {
      "type": "string",
      "enum": [
        "scheduled",
        "emergency",
        "inspection",
        "repair"
      ]
    },
    "priority": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high",
        "critical"
      ],
      "default": "medium"
    },
    "status": {
      "type": "string",
      "enum": [
        "open",
        "assigned",
        "in_progress",
        "completed",
        "cancelled"
      ],
      "default": "open"
    },
    "assigned_to": {
      "type": "string"
    },
    "started_date": {
      "type": "string",
      "format": "date"
    },
    "projected_completion_date": {
      "type": "string",
      "format": "date"
    },
    "completed_date": {
      "type": "string",
      "format": "date"
    },
    "actual_hours": {
      "type": "number"
    },
    "parts_used": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "part_id": {
            "type": "string",
            "description": "Linked FleetPart id when resolvable."
          },
          "source_part_id": {
            "type": "string",
            "description": "Original FleetMaster Parts id or 'custom' value, retained even when no current inventory row exists."
          },
          "part_name": {
            "type": "string"
          },
          "quantity": {
            "type": "number"
          },
          "cost": {
            "type": "number"
          }
        }
      }
    },
    "fluids_used": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "fluid_id": {
            "type": "string",
            "description": "Linked FleetFluid id when resolvable."
          },
          "source_fluid_id": {
            "type": "string",
            "description": "Original FleetMaster Fluids id or 'custom' value, retained even when no current inventory row exists."
          },
          "fluid_name": {
            "type": "string"
          },
          "quantity_quarts": {
            "type": "number",
            "description": "Historical FleetMaster field retained verbatim when present."
          },
          "quantity": {
            "type": "number",
            "description": "Normalized usage quantity for future CCS Fleet operations."
          },
          "unit": {
            "type": "string"
          },
          "cost": {
            "type": "number"
          }
        }
      }
    },
    "corrective_action": {
      "type": "string"
    },
    "before_photos": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "after_photos": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "problem_photos": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "notes": {
      "type": "string"
    },
    "total_cost": {
      "type": "number"
    },
    "mechanic_operation_key": {
      "type": "string",
      "description": "Durable receipt key for the most recently applied external mechanic start/progress mutation."
    },
    "mechanic_operation_fingerprint": {
      "type": "string",
      "description": "SHA-256 payload fingerprint bound to mechanic_operation_key so a request id cannot be reused with different mechanic data."
    },
    "mechanic_operation_applied_at": {
      "type": "string",
      "format": "date-time",
      "description": "Server timestamp for the most recently applied external mechanic mutation."
    },
    "completion_receipt_key": {
      "type": "string",
      "description": "Idempotency receipt for a completion operation."
    },
    "inventory_applied_at": {
      "type": "string",
      "format": "date-time"
    },
    "schedule_applied_at": {
      "type": "string",
      "format": "date-time"
    },
    "completion_notification_sent_at": {
      "type": "string",
      "format": "date-time"
    },
    "generation_key": {
      "type": "string",
      "description": "Deterministic scheduled-generation key preventing duplicate Fleet work orders."
    },
    "public_submission_key": {
      "type": "string",
      "description": "Anonymous public-report idempotency key. Used only by the tightly scoped Fleet public issue endpoint."
    },
    "public_reported_at": {
      "type": "string",
      "format": "date-time"
    },
    "public_reporter_name": {
      "type": "string"
    },
    "public_reporter_contact": {
      "type": "string"
    },
    "migration_source_app_id": {
      "type": "string"
    },
    "migration_source_entity": {
      "type": "string"
    },
    "migration_source_id": {
      "type": "string"
    },
    "migration_source_created_date": {
      "type": "string"
    },
    "migration_source_updated_date": {
      "type": "string"
    },
    "migration_source_created_by_id": {
      "type": "string",
      "description": "Original FleetMaster creator user/service id retained for historical audit."
    },
    "migration_source_created_by": {
      "type": "string",
      "description": "Original FleetMaster creator email retained for historical audit."
    },
    "migration_batch": {
      "type": "string"
    }
  },
  "required": [
    "work_order_number",
    "title"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "read": {
      "$or": [
        {
          "user_condition": {
            "role": "admin"
          }
        },
        {
          "user_condition": {
            "role": "user"
          }
        }
      ]
    },
    "update": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__fleet_server_only__"
      }
    }
  }
}

{
  "type": "object",
  "description": "Server-owned revocable bearer-link access for the standalone external Fleet mechanic portal. Raw access tokens are never stored; only SHA-256 hashes are persisted.",
  "properties": {
    "name": {
      "type": "string"
    },
    "token_hash": {
      "type": "string",
      "description": "SHA-256 hash of the raw mechanic bearer token. Raw token is shown only when generated and is never persisted."
    },
    "enabled": {
      "type": "boolean",
      "default": true
    },
    "allowed_actions": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "scope_mode": {
      "type": "string",
      "enum": [
        "all_active",
        "selected_equipment"
      ],
      "default": "all_active",
      "description": "Limits which active Fleet maintenance work orders this bearer link may view. Missing/legacy values are treated as all_active for backward compatibility."
    },
    "allowed_equipment_ids": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "FleetEquipment ids allowed when scope_mode is selected_equipment."
    },
    "expires_at": {
      "type": "string",
      "format": "date-time"
    },
    "last_used_at": {
      "type": "string",
      "format": "date-time"
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "name",
    "token_hash",
    "enabled"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__fleet_mechanic_service_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "__fleet_mechanic_service_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__fleet_mechanic_service_only__"
      }
    }
  },
  "name": "FleetMechanicAccess"
}

{
  "name": "FleetMigrationAudit",
  "type": "object",
  "description": "Admin-only dry-run, migration, and verification audit snapshots for the FleetMaster to CCS Fleet migration.",
  "properties": {
    "run_key": {
      "type": "string"
    },
    "mode": {
      "type": "string",
      "enum": [
        "dry_run",
        "migration",
        "verification"
      ]
    },
    "source_app_id": {
      "type": "string"
    },
    "destination_app_id": {
      "type": "string"
    },
    "started_at": {
      "type": "string",
      "format": "date-time"
    },
    "completed_at": {
      "type": "string",
      "format": "date-time"
    },
    "status": {
      "type": "string",
      "enum": [
        "running",
        "passed",
        "passed_with_findings",
        "failed"
      ],
