    "tax_amount": {
      "type": "number",
      "default": 0
    },
    "deposit_applied": {
      "type": "number",
      "default": 0,
      "description": "Customer deposit credited against this invoice."
    },
    "credit_applied": {
      "type": "number",
      "default": 0,
      "description": "In-store credit applied against this invoice (G-09); maintained server-side by the credit application."
    },
    "total": {
      "type": "number",
      "default": 0
    },
    "pay_url": {
      "type": "string",
      "description": "Online payment link for this invoice (Stripe-integration-ready placeholder \u2014 populated when a payment provider is wired)."
