    "paid_date": {
      "type": "string"
    },
    "voided_date": {
      "type": "string"
    },
    "void_reason": {
      "type": "string"
    },
    "notes": {
      "type": "string",
      "description": "Customer-facing notes printed on the invoice."
    },
    "internal_notes": {
      "type": "string"
    },
    "created_by": {
      "type": "string"
    },
    "updated_by": {
      "type": "string"
    },
    "source_summary": {
      "type": "object",
      "additionalProperties": true,
      "description": "Provenance: which record generated this invoice and under what review."
    },
    "fee_lines": {
      "type": "array",
