          "kind": {
            "type": "string",
            "enum": [
              "shipping",
              "postage",
              "discount",
              "fee"
            ],
            "description": "Fee classification."
          },
          "amount": {
            "type": "number",
            "description": "Signed amount; discounts are negative."
