    "splits_override_by": {
      "type": "string",
      "description": "Staff user/email who applied the manual split override."
    },
    "splits_override_at": {
      "type": "string",
      "format": "date-time",
      "description": "When the manual split override was applied."
    },
    "splits_override_reason": {
      "type": "string",
      "description": "Required reason recorded for the manual split override (audit trail)."
    }
  },
  "required": [
    "customer_id"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__invoice_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__invoice_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__invoice_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__invoice_backend_only__"
      }
    }
  }
}

